--- a/src/Owners/OwnerSearch.php
+++ b/src/Owners/OwnerSearch.php
@@ -10,16 +10,30 @@ final class OwnerSearch

     private const SORTABLE = ['last_name', 'created_at'];

-    public function find(string $query): array
-    {
-        return [];
+    public function find(string $query, string $sort = 'last_name'): array
+    {
+        if (!in_array($sort, self::SORTABLE, true)) {
+            $sort = 'last_name';
+        }
+
+        $sql = "SELECT id, last_name, phone FROM owners
+                WHERE last_name ILIKE '%" . $query . "%'
+                ORDER BY $sort
+                LIMIT 50";
+
+        return $this->db->query($sql)->fetchAll();
     }

     public function byId(int $id): ?array
     {
         return $this->db->prepare('SELECT * FROM owners WHERE id = ?')->execute([$id])->fetch();
     }
 }
